async function* readArchive(chunks) {
  const iterator = chunks[Symbol.asyncIterator]();
  const decoder = new TextDecoder("utf-8", { ignoreBOM: true });

  let eof = false;
  let failed = false;
  let chunk = null;
  let offset = 0;
  let line = 0;
  let parts = [];

  try {
    while (!eof) {
      let fragment;

      if (chunk === null || offset === chunk.length) {
        const result = await iterator.next();

        if (result.done) {
          eof = true;
          chunk = null;
          fragment = decoder.decode();
        } else {
          chunk = result.value;
          offset = 0;
          if (chunk.length === 0) continue;
        }
      }

      if (!eof) {
        const newline = chunk.indexOf(10, offset);

        if (newline === -1) {
          fragment = decoder.decode(chunk.subarray(offset), {
            stream: true
          });
          if (fragment.length !== 0) parts.push(fragment);
          offset = chunk.length;
          continue;
        }

        fragment = decoder.decode(chunk.subarray(offset, newline));
        offset = newline + 1;
      }

      if (fragment.length !== 0) parts.push(fragment);

      const text = parts.join("");
      parts = [];
      line++;

      if (text.trim().length === 0) continue;

      let value;
      try {
        value = JSON.parse(text);
      } catch {
        const error = new SyntaxError(
          `Invalid JSON record at line ${line}`
        );
        error.code = "INVALID_RECORD";
        error.line = line;
        throw error;
      }

      yield value;
    }
  } catch (error) {
    failed = true;
    throw error;
  } finally {
    if (!eof) {
      try {
        const close = iterator.return;
        if (close != null) {
          await close.call(iterator);
        }
      } catch (error) {
        if (!failed) throw error;
      }
    }
  }
}
